import math
from dataclasses import dataclass
from typing import Generic, TypeVar, Union

T = TypeVar('T')


@dataclass
class Some(Generic[T]):
    value: T


class NoneType:
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance


Nothing = NoneType()
Option = Union[Some[T], NoneType]


def safe_sqrt(n: float) -> Option[float]:
    if n < 0:
        return Nothing
    return Some(math.sqrt(n))


def print_result(opt: Option[float]) -> None:
    if isinstance(opt, Some):
        print(f"Root: {opt.value}")
    else:
        print("Error: Negative input")


if __name__ == "__main__":
    print_result(safe_sqrt(16.0))
    print_result(safe_sqrt(-4.0))

