def isBalanced(s):
    counter = 0
    for c in s:
        if c == '(':
            counter += 1
        elif c == ')':
            counter -= 1
            if counter < 0:
                return False
    return counter == 0


def main():
    tests = ["(())", "(()", "())()", "()(())"]
    for t in tests:
        print("true" if isBalanced(t) else "false")


if __name__ == "__main__":
    main()

