from dataclasses import dataclass
from typing import Union


@dataclass
class Leaf:
    value: int


@dataclass
class Branch:
    left: "Tree"
    value: int
    right: "Tree"


Tree = Union[Leaf, Branch]


def treeSum(tree: Tree) -> int:
    if isinstance(tree, Leaf):
        return tree.value
    return tree.value + treeSum(tree.left) + treeSum(tree.right)


def main() -> None:
    tree = Branch(
        left=Branch(left=Leaf(1), value=3, right=Leaf(4)),
        value=5,
        right=Branch(left=Leaf(8), value=8, right=Leaf(10)),
    )
    # Adjust to match the described tree: 8 has only a right child (10)
    tree = Branch(
        left=Branch(left=Leaf(1), value=3, right=Leaf(4)),
        value=5,
        right=Branch(left=Leaf(8), value=8, right=Leaf(10)),
    )
    # The above double-counts 8. Rebuild properly:
    right_subtree_with_only_right_child = Branch(
        left=Leaf(0), value=8, right=Leaf(10)
    )
    # To truly have only a right child while keeping the type, we represent
    # the "8" node as a Branch whose left is a sentinel. Instead, use a cleaner model:

    class NodeTree:
        pass

    # Restart with a model that supports optional children cleanly.
    @dataclass
    class N:
        value: int
        left: "Union[N, None]" = None
        right: "Union[N, None]" = None

    def tsum(n):
        if n is None:
            return 0
        return n.value + tsum(n.left) + tsum(n.right)

    root = N(5, N(3, N(1), N(4)), N(8, None, N(10)))
    print(tsum(root))


