import json

CONFIG_FILE = "app_config.json"


def create_config():
    config = {
        "app_name": "MyApp",
        "version": "1.0.0",
        "port": 8080,
        "features": ["logging", "auth", "api"],
    }
    with open(CONFIG_FILE, "w") as f:
        json.dump(config, f, indent=2)


def load_and_validate_config(path):
    with open(path, "r") as f:
        config = json.load(f)

    port = config["port"]
    if not (1024 <= port <= 65535):
        raise ValueError(f"Port {port} is not between 1024 and 65535")

    version = config["version"]
    if version.count(".") != 2:
        raise ValueError(f"Version '{version}' must be in X.Y.Z format")

    features = config["features"]
    if not features:
        raise ValueError("Features list must not be empty")

    return config


def main():
    create_config()
    config = load_and_validate_config(CONFIG_FILE)
    print(
        f"Loaded {config['app_name']} v{config['version']} "
        f"on port {config['port']} with {len(config['features'])} features"
    )


if __name__ == "__main__":
    main()

