T = TypeVar('T')


class Effect:
    """Marker class for tracking effects on functions."""
    def __init__(self, *effects: str):
        self.effects = effects

    def __call__(self, func: Callable[..., T]) -> Callable[..., T]:
        func.__effects__ = self.effects
