U = TypeVar("U")


@dataclass
class Ok(Generic[T]):
    value: T

    def bind(self, func: Callable[[T], "Result[U]"]) -> "Result[U]":
        return func(self.value)


@dataclass
class Err:
    message: str

    def bind(self, func: Callable) -> "Result":
        return self


Result = Union[Ok[T], Err]


def validate_age(age: int) -> Result[int]:
    if 0 <= age <= 150:
        return Ok(age)
    return Err("Age out of range")


def calculate_retirement_years(age: int) -> Result[int]:
    if age < 65:
        return Ok(65 - age)
    return Err("Already retired")


def process(age: int) -> None:
    result = validate_age(age).bind(calculate_retirement_years)
    if isinstance(result, Ok):
        print(f"Years to retirement: {result.value}")
    else:
        print(f"Error: {result.message}")


if __name__ == "__main__":
    for age in (30, 70, -5):
        process(age)

