-- Helper: Finds a key in a JSON object (represented as a list of key-value pairs)
pure func findKey(kvs: List[{key: string, value: Json}], target: string) -> Json {
  match kvs {
    [] => JNull,
    kv :: rest => if _str_eq(kv.key, target) then kv.value else findKey(rest, target)
  }
}

-- Helper: Extracts the age (as int) from a person's JSON object
pure func getAge(person: Json) -> Option[int] {
  match person {
    JObject(kvs) => match findKey(kvs, "age") {
      JNumber(f) => Some(floatToInt(f)), -- Convert float to int
      _ => None
    },
    _ => None
  }
}

-- Helper: Extracts the name (as string) from a person's JSON object
pure func getName(person: Json) -> Option[string] {
  match person {
    JObject(kvs) => match findKey(kvs, "name") {
      JString(s) => Some(s),
      _ => None
    },
    _ => None
  }
}

-- Filters a list of JSON objects (representing people) to keep only those aged 30 or older
pure func filterPeople(people: List[Json]) -> List[Json] {
  match people {
    [] => [],
    person :: rest =>
      match getAge(person) {
        Some(age) =>
          if age >= 30
          then person :: filterPeople(rest)
          else filterPeople(rest),
        None => filterPeople(rest) -- If age is missing or not a number, filter out
      }
  }
}

-- Prints the names of people in a list, one per line
func printNames(people: List[Json]) -> () ! {IO} {
  match people {
    [] => (),
    person :: rest => {
      match getName(person) {
        Some(name) => println(name),
        None => () -- If name is missing or not a string, skip this person
      };
      printNames(rest)
    }
  }
}

