  | TLam(string, Term)
  | TApp(Term, Term)

export pure func subst(term: Term, var: string, replacement: Term) -> Term {
  match term {
    TVar(s) => if s == var then replacement else TVar(s),
    TLam(param, body) => if param == var then TLam(param, body) else TLam(param, subst(body, var, replacement)),
    TApp(f, a) => TApp(subst(f, var, replacement), subst(a, var, replacement))
