from dataclasses import dataclass
from typing import Union


@dataclass
class TVar:
    name: str

    def __repr__(self):
        return f'TVar("{self.name}")'


@dataclass
class TLam:
    param: str
    body: 'Term'

    def __repr__(self):
        return f'TLam("{self.param}", {self.body!r})'


@dataclass
class TApp:
    func: 'Term'
    arg: 'Term'

    def __repr__(self):
        return f'TApp({self.func!r}, {self.arg!r})'


Term = Union[TVar, TLam, TApp]


def subst(term: Term, var: str, replacement: Term) -> Term:
    if isinstance(term, TVar):
        return replacement if term.name == var else term
    if isinstance(term, TLam):
        if term.param == var:
            return term
        return TLam(term.param, subst(term.body, var, replacement))
    if isinstance(term, TApp):
        return TApp(subst(term.func, var, replacement), subst(term.arg, var, replacement))
    raise TypeError(f"Unknown term: {term}")


def evaluate(term: Term) -> Term:
    if isinstance(term, TVar):
        return term
    if isinstance(term, TLam):
        return term
    if isinstance(term, TApp):
        f = evaluate(term.func)
        arg = evaluate(term.arg)
        if isinstance(f, TLam):
            return evaluate(subst(f.body, f.param, arg))
        return TApp(f, arg)
    raise TypeError(f"Unknown term: {term}")


if __name__ == "__main__":
    expr = TApp(TApp(TLam("x", TLam("y", TVar("x"))), TVar("1")), TVar("2"))
    result = evaluate(expr)
    print(result)

