from dataclasses import dataclass
from typing import Union


@dataclass
class Num:
    value: int


@dataclass
class Var:
    name: str


@dataclass
class Add:
    left: 'Expr'
    right: 'Expr'


@dataclass
class Mul:
    left: 'Expr'
    right: 'Expr'


@dataclass
class Let:
    name: str
    value: 'Expr'
    body: 'Expr'


Expr = Union[Num, Var, Add, Mul, Let]


def lookup(name, env):
    for n, v in env:
        if n == name:
            return v
    raise NameError(f"Unbound variable: {name}")


def eval(expr, env):
    if isinstance(expr, Num):
        return expr.value
    if isinstance(expr, Var):
        return lookup(expr.name, env)
    if isinstance(expr, Add):
        return eval(expr.left, env) + eval(expr.right, env)
    if isinstance(expr, Mul):
        return eval(expr.left, env) * eval(expr.right, env)
    if isinstance(expr, Let):
        val = eval(expr.value, env)
        return eval(expr.body, [(expr.name, val)] + env)
    raise TypeError(f"Unknown expression: {expr}")


