        return NONE
    return Some(lst[-1])


def safeHead(lst):
    if not lst:
        return NONE
    return Some(lst[0])


def flatMapOption(fn: Callable[[Any], Any], option):
    if isinstance(option, Some):
        return fn(option.value)
    return NONE


def run_test(lst, empty_msg="Empty list"):
    last = safeLast(lst)
    first_char = flatMapOption(lambda s: safeHead(list(s)), last)
    if isinstance(first_char, Some):
        print(f"Last starts with: {first_char.value}")
    else:
        print(empty_msg)


if __name__ == "__main__":
    run_test(["apple", "banana", "cherry"])
    run_test([])

