def create_sample_file(file_path: Path) -> None:
    """Creates a sample file with some mixed data."""
    try:
        with file_path.open("w", encoding="utf-8") as f:
            f.write("10\n20\n30\ninvalid_data\n40\n50\n")
    except IOError as e:
        print(f"Error writing to file: {e}", file=sys.stderr)
        sys.exit(1)

def process_data(file_path: Path) -> List[int]:
    """Reads data from a file, parses valid integers, and doubles them."""
    if not file_path.exists():
        raise FileNotFoundError(f"The file {file_path} does not exist.")

    try:
        with file_path.open("r", encoding="utf-8") as f:
            lines = f.readlines()

        processed_numbers = [
            int(line.strip()) * 2 
            for line in lines 
            if line.strip().isdigit()
        ]
        return processed_numbers
    except IOError as e:
        print(f"Error reading from file: {e}", file=sys.stderr)
        sys.exit(1)

