from dataclasses import dataclass
from typing import Union

class Color:
    pass

class Red(Color):
    pass

class Black(Color):
    pass

RED = Red()
BLACK = Black()

class RBTree:
    pass

class Empty(RBTree):
    pass

EMPTY = Empty()

@dataclass
class Node(RBTree):
    color: Color
    left: 'RBTree'
    value: int
    right: 'RBTree'

def is_red(t):
    return isinstance(t, Node) and isinstance(t.color, Red)

def is_black(t):
    return isinstance(t, Node) and isinstance(t.color, Black)

def balance(color, left, value, right):
    if isinstance(color, Black):
        # Left-Left
        if is_red(left) and is_red(left.left):
            a, x, b = left.left.left, left.left.value, left.left.right
            y = left.value
            c, z, d = left.right, value, right
            return Node(RED, Node(BLACK, a, x, b), y, Node(BLACK, c, z, d))
        # Left-Right
        if is_red(left) and is_red(left.right):
            a, x = left.left, left.value
            b, y, c = left.right.left, left.right.value, left.right.right
            z, d = value, right
            return Node(RED, Node(BLACK, a, x, b), y, Node(BLACK, c, z, d))
        # Right-Left
        if is_red(right) and is_red(right.left):
            a, x = left, value
            b, y, c = right.left.left, right.left.value, right.left.right
            z, d = right.value, right.right
            return Node(RED, Node(BLACK, a, x, b), y, Node(BLACK, c, z, d))
        # Right-Right
        if is_red(right) and is_red(right.right):
            a, x, b = left, value, right.left
            y = right.value
            c, z, d = right.right.left, right.right.value, right.right.right
            return Node(RED, Node(BLACK, a, x, b), y, Node(BLACK, c, z, d))
    return Node(color, left, value, right)

def ins(x, tree):
    if isinstance(tree, Empty):
        return Node(RED, EMPTY, x, EMPTY)
    if x < tree.value:
        return balance(tree.color, ins(x, tree.left), tree.value, tree.right)
    elif x > tree.value:
        return balance(tree.color, tree.left, tree.value, ins(x, tree.right))
    return tree

def insert(x, tree):
    t = ins(x, tree)
    return Node(BLACK, t.left, t.value, t.right)

def inorder(tree):
    if isinstance(tree, Empty):
        return []
    return inorder(tree.left) + [tree.value] + inorder(tree.right)

def main():
    values = [7, 3, 18, 10, 22, 8, 11, 26]
    tree = EMPTY
    for v in values:
        tree = insert(v, tree)
    print(inorder(tree))

if __name__ == "__main__":
    main()

