def transition(state: State, event: Event) -> State:
    """
    Takes a state and an event, and returns the new state.
    """
    match (state, event):
        case (Idle(floor), Call(target)):
            if target == floor:
                return DoorOpen(floor, 3)
            else:
                return Moving(floor, target)
        case (Moving(_, _), Tick()):
            # Moving + Tick doesn't change the state in this simplified model.
            return state
        case (Moving(_, target_floor), Arrive()):
            return DoorOpen(target_floor, 3)
        case (DoorOpen(floor, timer), Tick()):
            if timer > 1:
                return DoorOpen(floor, timer - 1)
            else:
                return Idle(floor)
        case _:
            # Any other combination results in no state change.
            return state

