from dataclasses import dataclass
from typing import Union

@dataclass
class Const:
    value: int

@dataclass
class Var:
    name: str

@dataclass
class Add:
    left: 'Expr'
    right: 'Expr'

@dataclass
class Mul:
    left: 'Expr'
    right: 'Expr'

Expr = Union[Const, Var, Add, Mul]


def diff(expr: Expr, var: str) -> Expr:
    if isinstance(expr, Const):
        return Const(0)
    if isinstance(expr, Var):
        return Const(1) if expr.name == var else Const(0)
    if isinstance(expr, Add):
        return Add(diff(expr.left, var), diff(expr.right, var))
    if isinstance(expr, Mul):
        return Add(
            Mul(expr.left, diff(expr.right, var)),
            Mul(expr.right, diff(expr.left, var)),
        )
    raise TypeError(f"Unknown expression: {expr}")


def simplify(expr: Expr) -> Expr:
    if isinstance(expr, Add):
        l = simplify(expr.left)
        r = simplify(expr.right)
        if isinstance(l, Const) and l.value == 0:
            return r
        if isinstance(r, Const) and r.value == 0:
            return l
        return Add(l, r)
    if isinstance(expr, Mul):
        l = simplify(expr.left)
        r = simplify(expr.right)
        if isinstance(l, Const) and l.value == 0:
            return Const(0)
        if isinstance(r, Const) and r.value == 0:
            return Const(0)
        if isinstance(l, Const) and l.value == 1:
            return r
        if isinstance(r, Const) and r.value == 1:
            return l
        return Mul(l, r)
    return expr


def showExpr(expr: Expr) -> str:
    if isinstance(expr, Const):
        return str(expr.value)
    if isinstance(expr, Var):
        return expr.name
    if isinstance(expr, Add):
        return f"({showExpr(expr.left)} + {showExpr(expr.right)})"
    if isinstance(expr, Mul):
        return f"({showExpr(expr.left)} * {showExpr(expr.right)})"
    raise TypeError(f"Unknown expression: {expr}")


if __name__ == "__main__":
    expr = Add(
        Add(
            Mul(Var("x"), Var("x")),
            Mul(Const(3), Var("x")),
        ),
        Const(5),
    )
    derivative = diff(expr, "x")
    simplified = simplify(derivative)
    print(showExpr(simplified))

