  | Node(Tree, int, Tree)

func mapTree(fn: int -> int, tree: Tree) -> Tree {
  match tree {
    Leaf(v) => Leaf(fn(v)),
    Node(left, v, right) => Node(mapTree(fn, left), fn(v), mapTree(fn, right))
  }
}

func foldTree(fn: int -> int -> int, acc: int, tree: Tree) -> int {
  match tree {
    Leaf(v) => fn(acc)(v),
    Node(left, v, right) => {
      let accLeft = foldTree(fn, acc, left);
      let accV = fn(accLeft)(v);
      foldTree(fn, accV, right)
    }
  }
}

func append[a](xs: [a], ys: [a]) -> [a] {
  match xs {
    [] => ys,
    x :: rest => x :: append(rest, ys)
  }
}

func treeToList(tree: Tree) -> [int] {
  match tree {
    Leaf(v) => [v],
    Node(left, v, right) => append(append(treeToList(left), [v]), treeToList(right))
  }
}

func treeDepth(tree: Tree) -> int {
  match tree {
    Leaf(_) => 1,
    Node(left, _, right) => {
      let ld = treeDepth(left);
      let rd = treeDepth(right);
      1 + (if ld > rd then ld else rd)
    }
  }
}

func filter[a](pred: a -> bool, xs: [a]) -> [a] {
  match xs {
    [] => [],
    x :: rest =>
      if pred(x)
      then x :: filter(pred, rest)
      else filter(pred, rest)
  }
}

func joinInts(xs: [int]) -> string {
