from dataclasses import dataclass
from typing import Union, List, Tuple


class Type:
    pass


@dataclass(frozen=True)
class TVar(Type):
    name: str


@dataclass(frozen=True)
class TInt(Type):
    pass


@dataclass(frozen=True)
class TBool(Type):
    pass


@dataclass(frozen=True)
class TFunc(Type):
    arg: Type
    res: Type


Subst = List[Tuple[str, Type]]


def apply(subst: Subst, t: Type) -> Type:
    if isinstance(t, TVar):
        for name, ty in subst:
            if name == t.name:
                return apply(subst, ty)
        return t
    if isinstance(t, TFunc):
        return TFunc(apply(subst, t.arg), apply(subst, t.res))
    return t


def compose(s1: Subst, s2: Subst) -> Subst:
    result = [(n, apply(s1, t)) for n, t in s2]
    result.extend(s1)
    return result


def unify(t1: Type, t2: Type) -> Subst:
    if isinstance(t1, TInt) and isinstance(t2, TInt):
        return []
    if isinstance(t1, TBool) and isinstance(t2, TBool):
        return []
    if isinstance(t1, TVar):
        return [(t1.name, t2)]
    if isinstance(t2, TVar):
        return [(t2.name, t1)]
    if isinstance(t1, TFunc) and isinstance(t2, TFunc):
        s1 = unify(t1.arg, t2.arg)
        s2 = unify(apply(s1, t1.res), apply(s1, t2.res))
        return compose(s2, s1)
    raise Exception(f"Cannot unify {t1} with {t2}")


def format_type(t: Type) -> str:
    if isinstance(t, TInt):
        return "TInt"
    if isinstance(t, TBool):
        return "TBool"
    if isinstance(t, TVar):
        return f"TVar({t.name})"
    if isinstance(t, TFunc):
        return f"TFunc({format_type(t.arg)}, {format_type(t.res)})"
    return str(t)


def main():
    t1 = TFunc(TVar("a"), TInt())
    t2 = TFunc(TBool(), TVar("b"))
    s = unify(t1, t2)
    seen = set()
    for name, _ in s:
        if name in seen:
            continue
        seen.add(name)
        resolved = apply(s, TVar(name))
        print(f"{name} = {format_type(resolved)}")


if __name__ == "__main__":
    main()
